STEP = 10
BIKE_PENCE = 200
MAX_BIKES = 3
GROUP_MIN = 4
CAP_PCT = 300


class UnknownRoute(KeyError):
    """The route code is not in the timetable."""


def base_fare(route):
    try:
        return ROUTES[route]
    except KeyError:
        raise UnknownRoute(route) from None


def _round_up(num, den):
    """The smallest multiple of STEP pence that is >= num/den."""
    steps = -(-num // (den * STEP))
